Running command: python - <<'PY'
import yaml,duckdb,pathlib
c=duckdb.connect('zendesk.duckdb',read_only=True)
d=yaml.safe_load(open('docs/data_contract.yaml'))
expected={'staging':{x['name']:x['columns'] for x in d['staging_contract']['tables']},'intermediate':{x['name']:x['columns'] for x in d['modeling_spec']['intermediate_models']},'marts':{x['name']:x['columns'] for x in d['modeling_spec']['marts_models']}}
for schema,models in expected.items():
 for name,cols in models.items():
  actual=c.execute(f'describe {schema}.{name}').fetchall()
  if [x[0] for x in actual] != [x['name'] for x in cols]: print('COL MISMATCH',schema,name,[x[0] for x in actual],[x['name'] for x in cols])
  for a,e in zip(actual,cols):
   if a[1].upper()!=e['data_type']: print('TYPE MISMATCH',schema,name,a[0],a[1],e['data_type'])
print('semicolons',[(str(p),';' in p.read_text()) for p in pathlib.Path('sql').rglob('*.sql') if ';' in p.read_text()])
for t in ['zendesk__ticket_enriched','zendesk__ticket_metrics']:
 schema='marts'; print(t,c.execute(f'select count(*) from {schema}.{t}').fetchone()[0])
PY

